import React, { useRef, useState, useEffect } from 'react';

const categoryConfig = {
  programming: { label:'Programming',       icon:'💻', color:'#e8799a' },
  dataSkills:  { label:'Data Science',       icon:'📊', color:'#b882d4' },
  tools:       { label:'Tools & Platforms',  icon:'🔧', color:'#e8b96a' },
};

const SkillBar = ({ skill, color, delay }) => {
  const [width, setWidth] = useState(0);
  const ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) { setTimeout(() => setWidth(skill.level), delay); observer.disconnect(); }
    }, { threshold: 0.3 });
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [skill.level, delay]);

  return (
    <div ref={ref} style={{ marginBottom:'1.25rem' }}>
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'0.5rem' }}>
        <div style={{ display:'flex', alignItems:'center', gap:'0.5rem' }}>
          <span style={{ fontSize:'1rem' }}>{skill.icon}</span>
          <span style={{ fontFamily:"'Nunito'", fontSize:'0.9rem', color:'#fdf0f4', fontWeight:600 }}>{skill.name}</span>
        </div>
        <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', color }}>{width}%</span>
      </div>
      <div style={{ height:7, background:'rgba(255,255,255,0.06)', borderRadius:4, overflow:'hidden' }}>
        <div style={{
          height:'100%', width:`${width}%`,
          background:`linear-gradient(90deg, ${color}, ${color}99)`,
          borderRadius:4, transition:'width 1.2s cubic-bezier(0.16,1,0.3,1)',
          boxShadow:`0 0 10px ${color}40`, position:'relative', overflow:'hidden',
        }}>
          <div style={{ position:'absolute', top:0, right:0, bottom:0, width:'25%', background:'rgba(255,255,255,0.18)', borderRadius:'0 4px 4px 0' }} />
        </div>
      </div>
    </div>
  );
};

const Skills = ({ data }) => {
  const [activeTab, setActiveTab] = useState('programming');
  const skills = data?.[activeTab] || [];

  return (
    <section style={{ padding:'100px 0' }}>
      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 2rem' }}>

        <div style={{ textAlign:'center', marginBottom:60 }}>
          <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', letterSpacing:'0.3em', textTransform:'uppercase', color:'#e8799a', display:'block', marginBottom:'0.75rem' }}>
            ✦ 02. skills
          </span>
          <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'clamp(2rem,5vw,3rem)', fontWeight:700, color:'#fdf0f4' }}>
            My <span style={{ color:'#b882d4', fontStyle:'italic' }}>Superpowers</span>
          </h2>
          <div style={{ width:60, height:3, background:'linear-gradient(90deg,#e8799a,#b882d4)', margin:'1.5rem auto 0', borderRadius:2 }} />
        </div>

        {/* Tab switcher */}
        <div style={{ display:'flex', justifyContent:'center', gap:'0.5rem', marginBottom:'3rem', flexWrap:'wrap' }}>
          {Object.entries(categoryConfig).map(([key, cfg]) => (
            <button key={key} onClick={() => setActiveTab(key)}
              style={{
                padding:'0.6rem 1.4rem', borderRadius:'50px',
                background: activeTab === key ? `${cfg.color}18` : 'transparent',
                border: `1.5px solid ${activeTab === key ? cfg.color : 'rgba(255,255,255,0.1)'}`,
                color: activeTab === key ? cfg.color : 'rgba(253,240,244,0.6)',
                fontFamily:"'Nunito'", fontWeight: activeTab === key ? 700 : 400,
                fontSize:'0.88rem', cursor:'pointer', transition:'all 0.2s ease',
                display:'flex', alignItems:'center', gap:'0.4rem',
              }}
            ><span>{cfg.icon}</span>{cfg.label}</button>
          ))}
        </div>

        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(320px,1fr))', gap:'1.5rem' }}>

          {/* Skill bars */}
          <div style={{ background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:20, backdropFilter:'blur(14px)', padding:'2rem' }}>
            {skills.map((skill, i) => (
              <SkillBar key={`${activeTab}-${skill.name}`} skill={skill} color={categoryConfig[activeTab]?.color || '#e8799a'} delay={i*100} />
            ))}
          </div>

          {/* Bubble chart */}
          <div style={{ background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:20, backdropFilter:'blur(14px)', padding:'2rem', display:'flex', flexDirection:'column', justifyContent:'center', alignItems:'center', gap:'1rem' }}>
            <div style={{ display:'flex', flexWrap:'wrap', gap:'0.75rem', justifyContent:'center' }}>
              {skills.map((skill, i) => {
                const color = categoryConfig[activeTab]?.color || '#e8799a';
                const size  = 62 + (skill.level / 100) * 30;
                return (
                  <div key={i} style={{
                    width:size, height:size, borderRadius:'50%',
                    background:`radial-gradient(circle at 35% 35%, ${color}28, ${color}08)`,
                    border:`1.5px solid ${color}40`,
                    display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center',
                    gap:'0.1rem', cursor:'default', transition:'all 0.3s ease',
                    boxShadow:`0 0 18px ${color}18`,
                  }}
                  onMouseEnter={e => { e.currentTarget.style.boxShadow=`0 0 28px ${color}45`; e.currentTarget.style.transform='scale(1.1)'; }}
                  onMouseLeave={e => { e.currentTarget.style.boxShadow=`0 0 18px ${color}18`; e.currentTarget.style.transform='scale(1)'; }}
                  >
                    <span style={{ fontSize:size > 75 ? '1.2rem':'0.9rem' }}>{skill.icon}</span>
                    <span style={{ fontFamily:"'DM Mono'", fontSize:'0.6rem', color, textAlign:'center', lineHeight:1 }}>{skill.level}%</span>
                  </div>
                );
              })}
            </div>
            <p style={{ fontFamily:"'DM Mono'", fontSize:'0.7rem', color:'rgba(253,240,244,0.3)', letterSpacing:'0.15em', textTransform:'uppercase', marginTop:'0.5rem' }}>Bubble size = proficiency</p>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
